create or replace function public.work_append_task_event(p_task_id uuid,p_assignment_id uuid,p_event_type text,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid := auth.uid(); begin if v_actor is null then raise exception 'Authentication required'; end if; if length(trim(coalesce(p_event_type,'')))=0 then raise exception 'Event type is required'; end if; insert into public.work_task_events(task_id,task_assignment_id,actor_id,event_type,metadata) values(p_task_id,p_assignment_id,v_actor,p_event_type,coalesce(p_metadata,'{}'::jsonb)); end; $$;
revoke all on function public.work_append_task_event(uuid,uuid,text,jsonb) from public,anon,authenticated;
create or replace function public.work_create_task(p_title text,p_description text,p_assignee_id uuid,p_requested_start_at timestamptz,p_requested_due_at timestamptz,p_priority text default 'normal',p_source_todo_id uuid default null,p_goal_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_task_id uuid; v_assignment_id uuid; begin if v_actor is null or not public.work_is_internal_user(v_actor) then raise exception 'Internal staff access required'; end if; if not public.work_is_internal_user(p_assignee_id) then raise exception 'Assignee must be an internal staff member'; end if; if length(trim(coalesce(p_title,'')))=0 then raise exception 'Task title is required'; end if; if p_priority not in ('low','normal','high','urgent') then raise exception 'Invalid priority'; end if; if p_requested_start_at is null or p_requested_due_at is null or p_requested_due_at<=p_requested_start_at then raise exception 'Task due time must be after start time'; end if; if p_source_todo_id is not null and not exists(select 1 from public.work_todos t where t.id=p_source_todo_id and t.owner_id=v_actor) then raise exception 'Source Todo is not available to the current user'; end if; if p_goal_id is not null and not public.work_can_read_goal(p_goal_id,v_actor) then raise exception 'Goal is not available to the current user'; end if; insert into public.work_tasks(title,description,created_by,source_todo_id,goal_id,priority,requested_start_at,requested_due_at,status) values(trim(p_title),nullif(trim(coalesce(p_description,'')),''),v_actor,p_source_todo_id,p_goal_id,p_priority,p_requested_start_at,p_requested_due_at,'open') returning id into v_task_id; insert into public.work_task_assignments(task_id,assignee_id,assigned_by,status,requested_start_at,requested_due_at) values(v_task_id,p_assignee_id,v_actor,'pending_acceptance',p_requested_start_at,p_requested_due_at) returning id into v_assignment_id; perform public.work_append_task_event(v_task_id,null,'task_created',jsonb_build_object('priority',p_priority)); perform public.work_append_task_event(v_task_id,v_assignment_id,'task_assigned',jsonb_build_object('assignee_id',p_assignee_id,'requested_start_at',p_requested_start_at,'requested_due_at',p_requested_due_at)); return v_task_id; end; $$;
create or replace function public.work_create_broadcast_task(p_title text,p_description text,p_requested_start_at timestamptz,p_requested_due_at timestamptz,p_priority text default 'normal',p_goal_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_task_id uuid; v_assignment_id uuid; v_assignee record; begin if v_actor is null or not public.work_is_admin(auth.uid()) then raise exception 'Only Admin or Super Admin can assign to everyone'; end if; if length(trim(coalesce(p_title,'')))=0 then raise exception 'Task title is required'; end if; if p_priority not in ('low','normal','high','urgent') then raise exception 'Invalid priority'; end if; if p_requested_start_at is null or p_requested_due_at is null or p_requested_due_at<=p_requested_start_at then raise exception 'Task due time must be after start time'; end if; if p_goal_id is not null and not public.work_can_read_goal(p_goal_id,v_actor) then raise exception 'Goal is not available to the current user'; end if; insert into public.work_tasks(title,description,created_by,goal_id,priority,requested_start_at,requested_due_at,status) values(trim(p_title),nullif(trim(coalesce(p_description,'')),''),v_actor,p_goal_id,p_priority,p_requested_start_at,p_requested_due_at,'open') returning id into v_task_id; perform public.work_append_task_event(v_task_id,null,'task_created',jsonb_build_object('broadcast',true,'priority',p_priority)); for v_assignee in select u.id from public.users u where public.is_internal_staff_role(u.role) order by u.created_at,u.id loop insert into public.work_task_assignments(task_id,assignee_id,assigned_by,status,requested_start_at,requested_due_at) values(v_task_id,v_assignee.id,v_actor,'pending_acceptance',p_requested_start_at,p_requested_due_at) returning id into v_assignment_id; perform public.work_append_task_event(v_task_id,v_assignment_id,'task_assigned',jsonb_build_object('assignee_id',v_assignee.id,'broadcast',true,'requested_start_at',p_requested_start_at,'requested_due_at',p_requested_due_at)); end loop; return v_task_id; end; $$;
create or replace function public.work_accept_task(p_assignment_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_assignment public.work_task_assignments%rowtype; begin select * into v_assignment from public.work_task_assignments where id=p_assignment_id for update; if not found then raise exception 'Task assignment not found'; end if; if v_actor is null or v_assignment.assignee_id<>v_actor then raise exception 'Only the assignee can accept this Task'; end if; if v_assignment.status<>'pending_acceptance' then raise exception 'Task is not awaiting acceptance'; end if; update public.work_task_assignments set status='active',accepted_at=now(),agreed_start_at=requested_start_at,agreed_due_at=requested_due_at,updated_at=now() where id=p_assignment_id; perform public.work_append_task_event(v_assignment.task_id,p_assignment_id,'task_accepted',jsonb_build_object('agreed_start_at',v_assignment.requested_start_at,'agreed_due_at',v_assignment.requested_due_at)); end; $$;
create or replace function public.work_reject_task(p_assignment_id uuid,p_reason_code text,p_note text) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_assignment public.work_task_assignments%rowtype; begin if p_reason_code not in ('outside_authority','wrong_assignee','insufficient_information','workload_unavailable','outside_skill','other') then raise exception 'Invalid rejection reason'; end if; if length(trim(coalesce(p_note,'')))=0 then raise exception 'Rejection explanation is required'; end if; select * into v_assignment from public.work_task_assignments where id=p_assignment_id for update; if not found then raise exception 'Task assignment not found'; end if; if v_actor is null or v_assignment.assignee_id<>v_actor then raise exception 'Only the assignee can reject this Task'; end if; if v_assignment.status<>'pending_acceptance' then raise exception 'Only a pending Task can be rejected'; end if; update public.work_task_assignments set status='returned',rejection_reason_code=p_reason_code,rejection_note=trim(p_note),returned_at=now(),updated_at=now() where id=p_assignment_id; perform public.work_append_task_event(v_assignment.task_id,p_assignment_id,'task_rejected',jsonb_build_object('reason_code',p_reason_code,'note',trim(p_note))); perform public.work_append_task_event(v_assignment.task_id,p_assignment_id,'task_returned','{}'::jsonb); end; $$;
create or replace function public.work_request_extension(p_assignment_id uuid,p_proposed_due_at timestamptz,p_reason text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_assignment public.work_task_assignments%rowtype; v_current_due timestamptz; v_request_id uuid; begin if length(trim(coalesce(p_reason,'')))=0 then raise exception 'Extension reason is required'; end if; select * into v_assignment from public.work_task_assignments where id=p_assignment_id for update; if not found then raise exception 'Task assignment not found'; end if; if v_actor is null or v_assignment.assignee_id<>v_actor then raise exception 'Only the assignee can request an extension'; end if; if v_assignment.status not in ('pending_acceptance','active') then raise exception 'This Task cannot request an extension in its current state'; end if; if exists(select 1 from public.work_task_extension_requests r where r.task_assignment_id=p_assignment_id and r.status='pending') then raise exception 'An extension request is already pending'; end if; v_current_due:=case when v_assignment.status='active' then v_assignment.agreed_due_at else v_assignment.requested_due_at end; if v_current_due is null or p_proposed_due_at is null or p_proposed_due_at<=v_current_due then raise exception 'Proposed deadline must be later than the current deadline'; end if; insert into public.work_task_extension_requests(task_assignment_id,requested_by,original_due_at,proposed_due_at,reason,status) values(p_assignment_id,v_actor,v_current_due,p_proposed_due_at,trim(p_reason),'pending') returning id into v_request_id; if v_assignment.status='pending_acceptance' then update public.work_task_assignments set status='extension_pending',updated_at=now() where id=p_assignment_id; end if; perform public.work_append_task_event(v_assignment.task_id,p_assignment_id,'extension_requested',jsonb_build_object('request_id',v_request_id,'original_due_at',v_current_due,'proposed_due_at',p_proposed_due_at,'reason',trim(p_reason))); return v_request_id; end; $$;
create or replace function public.work_decide_extension(p_request_id uuid,p_decision text,p_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_request public.work_task_extension_requests%rowtype; v_assignment public.work_task_assignments%rowtype; v_task public.work_tasks%rowtype; begin if p_decision not in ('approved','declined') then raise exception 'Decision must be approved or declined'; end if; select * into v_request from public.work_task_extension_requests where id=p_request_id for update; if not found then raise exception 'Extension request not found'; end if; if v_request.status<>'pending' then raise exception 'Extension request has already been decided'; end if; select * into v_assignment from public.work_task_assignments where id=v_request.task_assignment_id for update; select * into v_task from public.work_tasks where id=v_assignment.task_id for update; if v_actor is null then raise exception 'Authentication required'; end if; if v_assignment.assigned_by<>v_actor and v_task.created_by<>v_actor and not public.work_is_admin(v_actor) then raise exception 'Only the assigner or Admin can decide an extension'; end if; if p_decision='approved' then if v_assignment.status='extension_pending' then update public.work_task_assignments set status='active',accepted_at=coalesce(accepted_at,now()),agreed_start_at=coalesce(agreed_start_at,requested_start_at),agreed_due_at=v_request.proposed_due_at,updated_at=now() where id=v_assignment.id; elsif v_assignment.status='active' then update public.work_task_assignments set agreed_due_at=v_request.proposed_due_at,updated_at=now() where id=v_assignment.id; else raise exception 'Task is not in a state where an extension can be approved'; end if; else if v_assignment.status='extension_pending' then update public.work_task_assignments set status='pending_acceptance',updated_at=now() where id=v_assignment.id; elsif v_assignment.status<>'active' then raise exception 'Task is not in a state where an extension can be declined'; end if; end if; update public.work_task_extension_requests set status=p_decision,decided_by=v_actor,decided_at=now(),decision_note=nullif(trim(coalesce(p_note,'')),'') where id=p_request_id; perform public.work_append_task_event(v_task.id,v_assignment.id,case when p_decision='approved' then 'extension_approved' else 'extension_declined' end,jsonb_build_object('request_id',p_request_id,'original_due_at',v_request.original_due_at,'proposed_due_at',v_request.proposed_due_at,'decision_note',nullif(trim(coalesce(p_note,'')),''))); if p_decision='approved' and v_assignment.status='extension_pending' then perform public.work_append_task_event(v_task.id,v_assignment.id,'task_accepted',jsonb_build_object('accepted_via_extension',true,'agreed_due_at',v_request.proposed_due_at)); end if; end; $$;
create or replace function public.work_complete_task(p_assignment_id uuid,p_completion_note text) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_assignment public.work_task_assignments%rowtype; begin if length(trim(coalesce(p_completion_note,'')))=0 then raise exception 'Completion note is required'; end if; select * into v_assignment from public.work_task_assignments where id=p_assignment_id for update; if not found then raise exception 'Task assignment not found'; end if; if v_actor is null or v_assignment.assignee_id<>v_actor then raise exception 'Only the assignee can complete this Task'; end if; if v_assignment.status<>'active' then raise exception 'Only an active Task can be completed'; end if; update public.work_task_assignments set status='completed',completed_at=now(),completion_note=trim(p_completion_note),updated_at=now() where id=p_assignment_id; perform public.work_append_task_event(v_assignment.task_id,p_assignment_id,'task_completed',jsonb_build_object('completion_note',trim(p_completion_note))); if not exists(select 1 from public.work_task_assignments a where a.task_id=v_assignment.task_id and a.status not in ('completed','cancelled')) then update public.work_tasks set status='completed',updated_at=now() where id=v_assignment.task_id; end if; end; $$;
create or replace function public.work_reassign_returned_task(p_assignment_id uuid,p_new_assignee_id uuid,p_requested_start_at timestamptz,p_requested_due_at timestamptz,p_priority text,p_note text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_assignment public.work_task_assignments%rowtype; v_task public.work_tasks%rowtype; v_new_assignment_id uuid; v_assignment_count integer; begin select * into v_assignment from public.work_task_assignments where id=p_assignment_id for update; if not found then raise exception 'Task assignment not found'; end if; select * into v_task from public.work_tasks where id=v_assignment.task_id for update; if v_actor is null or (v_task.created_by<>v_actor and not public.work_is_admin(v_actor)) then raise exception 'Only the Task creator or Admin can reassign returned work'; end if; if v_assignment.status<>'returned' then raise exception 'Only returned Tasks can be reassigned'; end if; if not public.work_is_internal_user(p_new_assignee_id) then raise exception 'New assignee must be internal staff'; end if; if p_requested_start_at is null or p_requested_due_at is null or p_requested_due_at<=p_requested_start_at then raise exception 'Task due time must be after start time'; end if; if p_priority not in ('low','normal','high','urgent') then raise exception 'Invalid priority'; end if; select count(*) into v_assignment_count from public.work_task_assignments where task_id=v_task.id; if v_assignment_count=1 then update public.work_tasks set priority=p_priority,requested_start_at=p_requested_start_at,requested_due_at=p_requested_due_at,updated_at=now() where id=v_task.id; elsif p_priority<>v_task.priority then raise exception 'Priority cannot differ when reassigning one recipient of a broadcast Task'; end if; insert into public.work_task_assignments(task_id,assignee_id,assigned_by,status,requested_start_at,requested_due_at) values(v_task.id,p_new_assignee_id,v_actor,'pending_acceptance',p_requested_start_at,p_requested_due_at) returning id into v_new_assignment_id; perform public.work_append_task_event(v_task.id,v_new_assignment_id,'task_reassigned',jsonb_build_object('previous_assignment_id',p_assignment_id,'new_assignee_id',p_new_assignee_id,'requested_start_at',p_requested_start_at,'requested_due_at',p_requested_due_at,'note',nullif(trim(coalesce(p_note,'')),''))); return v_new_assignment_id; end; $$;
create or replace function public.work_cancel_assignment(p_assignment_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_assignment public.work_task_assignments%rowtype; v_task public.work_tasks%rowtype; begin if length(trim(coalesce(p_reason,'')))=0 then raise exception 'Cancellation reason is required'; end if; select * into v_assignment from public.work_task_assignments where id=p_assignment_id for update; if not found then raise exception 'Task assignment not found'; end if; select * into v_task from public.work_tasks where id=v_assignment.task_id for update; if v_actor is null or (v_assignment.assigned_by<>v_actor and v_task.created_by<>v_actor and not public.work_is_admin(v_actor)) then raise exception 'Only the assigner or Admin can cancel this Task'; end if; if v_assignment.status in ('completed','cancelled') then raise exception 'This Task assignment is already closed'; end if; update public.work_task_assignments set status='cancelled',updated_at=now() where id=p_assignment_id; perform public.work_append_task_event(v_task.id,p_assignment_id,'task_cancelled',jsonb_build_object('reason',trim(p_reason))); if not exists(select 1 from public.work_task_assignments a where a.task_id=v_task.id and a.status<>'cancelled') then update public.work_tasks set status='cancelled',cancelled_at=now(),updated_at=now() where id=v_task.id; elsif not exists(select 1 from public.work_task_assignments a where a.task_id=v_task.id and a.status not in ('completed','cancelled')) then update public.work_tasks set status='completed',updated_at=now() where id=v_task.id; end if; end; $$;
revoke all on function public.work_create_task(text,text,uuid,timestamptz,timestamptz,text,uuid,uuid) from public,anon; revoke all on function public.work_create_broadcast_task(text,text,timestamptz,timestamptz,text,uuid) from public,anon; revoke all on function public.work_accept_task(uuid) from public,anon; revoke all on function public.work_reject_task(uuid,text,text) from public,anon; revoke all on function public.work_request_extension(uuid,timestamptz,text) from public,anon; revoke all on function public.work_decide_extension(uuid,text,text) from public,anon; revoke all on function public.work_complete_task(uuid,text) from public,anon; revoke all on function public.work_reassign_returned_task(uuid,uuid,timestamptz,timestamptz,text,text) from public,anon; revoke all on function public.work_cancel_assignment(uuid,text) from public,anon;
grant execute on function public.work_create_task(text,text,uuid,timestamptz,timestamptz,text,uuid,uuid) to authenticated; grant execute on function public.work_create_broadcast_task(text,text,timestamptz,timestamptz,text,uuid) to authenticated; grant execute on function public.work_accept_task(uuid) to authenticated; grant execute on function public.work_reject_task(uuid,text,text) to authenticated; grant execute on function public.work_request_extension(uuid,timestamptz,text) to authenticated; grant execute on function public.work_decide_extension(uuid,text,text) to authenticated; grant execute on function public.work_complete_task(uuid,text) to authenticated; grant execute on function public.work_reassign_returned_task(uuid,uuid,timestamptz,timestamptz,text,text) to authenticated; grant execute on function public.work_cancel_assignment(uuid,text) to authenticated;
